import { useEffect, useState } from "react";
import "./projectGallery.css";

export default function TwoDDesigns() {
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  useEffect(() => {
    if (!isPreviewOpen) return undefined;

    const closeOnEscape = (event) => {
      if (event.key === "Escape") {
        setIsPreviewOpen(false);
      }
    };

    window.addEventListener("keydown", closeOnEscape);
    return () => window.removeEventListener("keydown", closeOnEscape);
  }, [isPreviewOpen]);

  return (
    <main className="project-designs-gallery">
      <button
        type="button"
        className="project-card-2d-button"
        onClick={() => setIsPreviewOpen(true)}
        aria-label="View 2D design image"
      >
        <img src="/2d_designs.png" alt="2D Designs" className="project-card-2d" />
      </button>

      {isPreviewOpen && (
        <div
          className="image-preview-backdrop"
          onClick={() => setIsPreviewOpen(false)}
          role="presentation"
        >
          <div
            className="image-preview-dialog"
            role="dialog"
            aria-modal="true"
            aria-label="2D design image preview"
            onClick={(event) => event.stopPropagation()}
          >
            <button
              type="button"
              className="image-preview-close"
              onClick={() => setIsPreviewOpen(false)}
              aria-label="Close image preview"
            >
              &times;
            </button>
            <img src="/2d_designs.png" alt="2D Designs" />
          </div>
        </div>
      )}
    </main>
  );
}
